INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (16,16,'["Comment élaborez-vous un cahier des charges de gestion de projet urbain, et quels indicateurs de performance utilisez-vous pour en assurer le suivi ?", "Dans le cadre d''un projet d''aménagement territorial, comment coordonnez-vous les interventions entre les différents acteurs techniques, administratifs et financiers ?", "Quelle méthodologie appliquez-vous pour identifier et gérer les risques d''un projet d''infrastructure urbaine à différentes phases de son exécution ?", "Parlez-nous d''un projet concret que vous avez piloté ou auquel vous avez contribué significativement durant vos 4 années d''expérience, et quel a été votre rôle précis ?", "En quoi votre formation en architecture et urbanisme à l''ESA de Fès vous apporte-t-elle une valeur ajoutée pour un poste orienté gestion et coordination de projets ?", "Avez-vous déjà travaillé dans un environnement multi-parties prenantes incluant des collectivités territoriales ou des institutions publiques ? Comment avez-vous géré les contraintes réglementaires rencontrées ?", "Pourquoi souhaitez-vous rejoindre l''ADER Fès-Meknès à ce stade de votre parcours professionnel ?", "Où vous projetez-vous dans 5 ans, et en quoi ce poste de CGM s''inscrit-il dans votre trajectoire professionnelle ?", "Que savez-vous des missions et des projets structurants portés par l''ADER Fès-Meknès dans la région ?", "Quelle est votre lecture des enjeux actuels du développement régional au Maroc, notamment dans le contexte de la régionalisation avancée ?"]','[]','{}','2026-08-27 13:28:42.247262') ON CONFLICT (id) DO NOTHING;